from __future__ import annotations

from starlette.datastructures import QueryParams
from starlette.requests import Request
from starlette.responses import JSONResponse
from starlette.types import Receive, Scope, Send
from tests.types import TestClientFactory


def test_query_params_equal_plain_dict() -> None:
    q = QueryParams("page=2&sort=name")
    assert q == {"page": "2", "sort": "name"}
    assert {"page": "2", "sort": "name"} == q
    assert q == {"sort": "name", "page": "2"}


def test_query_params_not_equal_different_dict() -> None:
    q = QueryParams("page=2&sort=name")
    assert q != {"page": "3", "sort": "name"}
    assert q != {"page": "2"}
    assert q != {"page": "2", "sort": "name", "extra": "1"}
    assert QueryParams("") == {}


def test_query_params_still_compare_to_query_params() -> None:
    assert QueryParams("a=1&b=2") == QueryParams({"b": "2", "a": "1"})
    assert QueryParams("a=1") != "a=1"


def test_request_query_params_equal_dict(test_client_factory: TestClientFactory) -> None:
    async def app(scope: Scope, receive: Receive, send: Send) -> None:
        request = Request(scope, receive)
        matches = request.query_params == {"page": "2", "sort": "name"}
        await JSONResponse({"matches": matches})(scope, receive, send)

    client = test_client_factory(app)
    assert client.get("/?page=2&sort=name").json() == {"matches": True}
    assert client.get("/?page=3&sort=name").json() == {"matches": False}

from __future__ import annotations

from urllib.parse import unquote

import pytest

from starlette.requests import Request
from starlette.responses import JSONResponse
from starlette.routing import Route, Router
from tests.types import TestClientFactory


def echo(request: Request) -> JSONResponse:
    return JSONResponse({key: str(value) for key, value in request.path_params.items()})


router = Router(
    routes=[
        Route("/users/{username}", echo, name="user"),
        Route("/files/{path:path}", echo, name="file"),
    ]
)


def _assert_safe(url: str) -> None:
    assert url.isascii()
    for char in (" ", "?", "#"):
        assert char not in url


@pytest.mark.parametrize("username", ["Zoë Smith", "a?b#c", "100% sure"])
def test_str_param_is_percent_encoded(username: str) -> None:
    url = str(router.url_path_for("user", username=username))
    _assert_safe(url)
    assert url.startswith("/users/")
    assert unquote(url) == f"/users/{username}"


def test_path_param_is_percent_encoded() -> None:
    url = str(router.url_path_for("file", path="docs/my file.txt"))
    _assert_safe(url)
    assert unquote(url) == "/files/docs/my file.txt"


def test_plain_values_are_unchanged() -> None:
    assert router.url_path_for("user", username="tomchristie") == "/users/tomchristie"
    assert router.url_path_for("file", path="docs/readme.txt") == "/files/docs/readme.txt"


def test_encoded_url_round_trips(test_client_factory: TestClientFactory) -> None:
    client = test_client_factory(router)
    url = str(router.url_path_for("user", username="Zoë Smith"))
    assert client.get(url).json() == {"username": "Zoë Smith"}
